CREATE TABLE IF NOT EXISTS delivery_task(id VARCHAR(36) PRIMARY KEY,tenant VARCHAR(40) NOT NULL,name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS delivery_outbox(event_id VARCHAR(36) PRIMARY KEY,body VARCHAR(4096) NOT NULL,sent BOOLEAN NOT NULL,attempts INT NOT NULL,claim_token VARCHAR(36),lease_until BIGINT,retry_at BIGINT NOT NULL,last_error VARCHAR(120));
CREATE TABLE IF NOT EXISTS delivery_inbox(event_id VARCHAR(36) PRIMARY KEY,body VARCHAR(4096) NOT NULL);
CREATE TABLE IF NOT EXISTS delivery_result(task_id VARCHAR(36) PRIMARY KEY,tenant VARCHAR(40) NOT NULL,executions INT NOT NULL);
